// See mods_facade.h. melee-unlocked's catalog is built in from the fetched tree's mods-catalog-2.json
// (mods_catalog_json.h, generated by mu-engine/app/CMakeLists.txt); downloads go through the system's libcurl.
// SPDX-License-Identifier: GPL-3.0-or-later
#include "mods_facade.h"
#include "mod_install.h"
#include "mi_fetch_curl.h"
#include "mods_catalog_json.h"

#include <cstdio>
#include <memory>

namespace mu_mods {
namespace {
std::unique_ptr<modinstall::Manager> g_manager;
std::string g_mods_dir;
}
bool available() { return true; }
void configure(const std::string& mods_dir, const std::string& disc_path) {
  if (g_manager && g_manager->config().disc_path == disc_path && g_mods_dir == mods_dir) return;
  if (g_manager && g_manager->busy()) return;
  modinstall::Config c;
  c.mods_dir = mods_dir; c.cache_dir = mods_dir + "/.cache"; c.disc_path = disc_path;
  c.catalog_json = kModsCatalogJson;
  c.fetcher = modinstall::curl_fetcher();
  c.log = [](const std::string& line) { std::fprintf(stderr, "%s\n", line.c_str()); };
  g_manager = std::make_unique<modinstall::Manager>(c);
  g_mods_dir = mods_dir;
}
std::vector<Row> rows() {
  std::vector<Row> out;
  if (!g_manager || !g_manager->catalog_ok()) return out;
  for (const modinstall::ModStatus& s : g_manager->list()) {
    Row r;
    r.id = s.mod.id; r.name = s.mod.name; r.version = s.installed_version.empty() ? s.mod.version : s.installed_version;
    r.note = s.mod.note; r.line = s.line; r.percent = s.percent; r.automatic = s.automatic; r.file_ready = s.file_ready; r.failed = s.failed;
    r.state = s.state == modinstall::State::Installed ? 1 : s.state == modinstall::State::UpdateAvailable ? 2 : s.state == modinstall::State::Working ? 3 : 0;
    out.push_back(r);
  }
  return out;
}
bool install(const std::string& id, std::string* why) { return g_manager && g_manager->install(id, why); }
bool remove(const std::string& id, std::string* why) { return g_manager && g_manager->remove(id, why); }
bool busy() { return g_manager && g_manager->busy(); }
void cancel() { if (g_manager) g_manager->cancel(); }
std::string catalog_error() { return !g_manager ? "the mod installer is not set up" : g_manager->catalog_error(); }
std::string downloads_dir() { return g_mods_dir + "/Downloads"; }
}
